#include "physics/CCPhysicsCollisionPair.h"
#if CC_USE_PHYSICS

#include <cmath>
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

PhysicsCollisionPair::PhysicsCollisionPair()
: _arbiter(nullptr)
, _shapeA(nullptr)
, _shapeB(nullptr)
, _valid(false)
, _ignored(false)
{
}

PhysicsCollisionPair::~PhysicsCollisionPair()
{
}

bool PhysicsCollisionPair::init(cpArbiter* arbiter)
{
    if (arbiter == nullptr)
    {
        return false;
    }

    update(arbiter);
    return true;
}

void PhysicsCollisionPair::update(cpArbiter* arbiter)
{
    _arbiter = arbiter;
    _valid = arbiter != nullptr;
    _ignored = false;

    _shapeA = nullptr;
    _shapeB = nullptr;

    if (_arbiter != nullptr)
    {
        cpShape* a = nullptr;
        cpShape* b = nullptr;
        cpArbiterGetShapes(_arbiter, &a, &b);

        if (a != nullptr)
        {
            _shapeA = static_cast<PhysicsShape*>(cpShapeGetUserData(a));
        }
        if (b != nullptr)
        {
            _shapeB = static_cast<PhysicsShape*>(cpShapeGetUserData(b));
        }
    }
}

void PhysicsCollisionPair::invalidate()
{
    _arbiter = nullptr;
    _shapeA = nullptr;
    _shapeB = nullptr;
    _valid = false;
    _ignored = false;
}

PhysicsShape* PhysicsCollisionPair::getShapeA() const
{
    return _shapeA;
}

PhysicsShape* PhysicsCollisionPair::getShapeB() const
{
    return _shapeB;
}

PhysicsBody* PhysicsCollisionPair::getBodyA() const
{
    return _shapeA != nullptr ? _shapeA->getBody() : nullptr;
}

PhysicsBody* PhysicsCollisionPair::getBodyB() const
{
    return _shapeB != nullptr ? _shapeB->getBody() : nullptr;
}

int PhysicsCollisionPair::getContactCount() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0;
    }

    return cpArbiterGetCount(_arbiter);
}

CollisionPoint PhysicsCollisionPair::getContactPoint(int index) const
{
    CollisionPoint point;
    point.pointA = Vec2::ZERO;
    point.pointB = Vec2::ZERO;
    point.normal = Vec2::ZERO;
    point.depth = 0.0f;
    point.normalImpulse = 0.0f;
    point.tangentImpulse = 0.0f;

    if (!_valid || _arbiter == nullptr || index < 0 || index >= cpArbiterGetCount(_arbiter))
    {
        return point;
    }

    point.pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(_arbiter, index));
    point.pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(_arbiter, index));
    point.normal = PhysicsHelper::cpv2point(cpArbiterGetNormal(_arbiter));
    point.depth = PhysicsHelper::cpfloat2float(cpArbiterGetDepth(_arbiter, index));

    // Chipmunk only exposes the total impulse of the arbiter, so split it
    // evenly over the contact points, projected on the normal/tangent axes.
    int count = cpArbiterGetCount(_arbiter);
    if (count > 0)
    {
        cpVect normal = cpArbiterGetNormal(_arbiter);
        cpVect impulse = cpArbiterTotalImpulse(_arbiter);
        point.normalImpulse = PhysicsHelper::cpfloat2float(cpvdot(impulse, normal) / count);
        point.tangentImpulse = PhysicsHelper::cpfloat2float(cpvdot(impulse, cpvperp(normal)) / count);
    }

    return point;
}

void PhysicsCollisionPair::getContactPoints(CollisionPoint* outPoints, int* outCount) const
{
    if (outCount == nullptr)
    {
        return;
    }

    if (outPoints == nullptr || !_valid || _arbiter == nullptr)
    {
        *outCount = 0;
        return;
    }

    int count = cpArbiterGetCount(_arbiter);
    for (int i = 0; i < count; ++i)
    {
        outPoints[i] = getContactPoint(i);
    }
    *outCount = count;
}

Vec2 PhysicsCollisionPair::getContactNormal() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return Vec2::ZERO;
    }

    return PhysicsHelper::cpv2point(cpArbiterGetNormal(_arbiter));
}

float PhysicsCollisionPair::getTotalNormalImpulse() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    cpVect impulse = cpArbiterTotalImpulse(_arbiter);
    cpVect normal = cpArbiterGetNormal(_arbiter);
    return PhysicsHelper::cpfloat2float(cpvdot(impulse, normal));
}

float PhysicsCollisionPair::getTotalTangentImpulse() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    cpVect impulse = cpArbiterTotalImpulse(_arbiter);
    cpVect normal = cpArbiterGetNormal(_arbiter);
    return PhysicsHelper::cpfloat2float(cpvdot(impulse, cpvperp(normal)));
}

Vec2 PhysicsCollisionPair::getTotalImpulse() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return Vec2::ZERO;
    }

    return PhysicsHelper::cpv2point(cpArbiterTotalImpulse(_arbiter));
}

float PhysicsCollisionPair::getKineticEnergy() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    return PhysicsHelper::cpfloat2float(cpArbiterTotalKE(_arbiter));
}

float PhysicsCollisionPair::getRestitution() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    return PhysicsHelper::cpfloat2float(cpArbiterGetRestitution(_arbiter));
}

void PhysicsCollisionPair::setRestitution(float restitution)
{
    if (!_valid || _arbiter == nullptr)
    {
        return;
    }

    cpArbiterSetRestitution(_arbiter, (cpFloat)restitution);
}

float PhysicsCollisionPair::getFriction() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    return PhysicsHelper::cpfloat2float(cpArbiterGetFriction(_arbiter));
}

void PhysicsCollisionPair::setFriction(float friction)
{
    if (!_valid || _arbiter == nullptr)
    {
        return;
    }

    cpArbiterSetFriction(_arbiter, (cpFloat)friction);
}

Vec2 PhysicsCollisionPair::getSurfaceVelocity() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return Vec2::ZERO;
    }

    return PhysicsHelper::cpv2point(cpArbiterGetSurfaceVelocity(_arbiter));
}

void PhysicsCollisionPair::setSurfaceVelocity(const Vec2& velocity)
{
    if (!_valid || _arbiter == nullptr)
    {
        return;
    }

    cpArbiterSetSurfaceVelocity(_arbiter, PhysicsHelper::point2cpv(velocity));
}

bool PhysicsCollisionPair::isFirstContact() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return false;
    }

    return cpArbiterIsFirstContact(_arbiter) == cpTrue;
}

bool PhysicsCollisionPair::isRemoval() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return false;
    }

    return cpArbiterIsRemoval(_arbiter) == cpTrue;
}

bool PhysicsCollisionPair::isSensor() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return false;
    }

    cpShape* a = nullptr;
    cpShape* b = nullptr;
    cpArbiterGetShapes(_arbiter, &a, &b);

    bool sensorA = a != nullptr && cpShapeGetSensor(a) == cpTrue;
    bool sensorB = b != nullptr && cpShapeGetSensor(b) == cpTrue;
    return sensorA || sensorB;
}

void PhysicsCollisionPair::ignore()
{
    if (!_valid || _arbiter == nullptr)
    {
        return;
    }

    cpArbiterIgnore(_arbiter);
    _ignored = true;
}

bool PhysicsCollisionPair::isIgnored() const
{
    return _ignored;
}

float PhysicsCollisionPair::computeSeparatingVelocity() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    cpBody* bodyA = nullptr;
    cpBody* bodyB = nullptr;
    cpArbiterGetBodies(_arbiter, &bodyA, &bodyB);
    if (bodyA == nullptr || bodyB == nullptr)
    {
        return 0.0f;
    }

    // The normal points from shape A to shape B, so a positive projection of
    // the relative velocity (B - A) on the normal means the bodies separate.
    cpVect point = PhysicsHelper::point2cpv(computeContactCenter());
    cpVect velA = cpBodyGetVelocityAtWorldPoint(bodyA, point);
    cpVect velB = cpBodyGetVelocityAtWorldPoint(bodyB, point);
    cpVect normal = cpArbiterGetNormal(_arbiter);

    return PhysicsHelper::cpfloat2float(cpvdot(cpvsub(velB, velA), normal));
}

float PhysicsCollisionPair::computeOverlap() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return 0.0f;
    }

    float overlap = 0.0f;
    int count = cpArbiterGetCount(_arbiter);
    for (int i = 0; i < count; ++i)
    {
        overlap += PhysicsHelper::cpfloat2float(cpArbiterGetDepth(_arbiter, i));
    }

    return overlap;
}

Vec2 PhysicsCollisionPair::computeRelativeVelocity() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return Vec2::ZERO;
    }

    cpBody* bodyA = nullptr;
    cpBody* bodyB = nullptr;
    cpArbiterGetBodies(_arbiter, &bodyA, &bodyB);
    if (bodyA == nullptr || bodyB == nullptr)
    {
        return Vec2::ZERO;
    }

    cpVect point = PhysicsHelper::point2cpv(computeContactCenter());
    cpVect velA = cpBodyGetVelocityAtWorldPoint(bodyA, point);
    cpVect velB = cpBodyGetVelocityAtWorldPoint(bodyB, point);

    return PhysicsHelper::cpv2point(cpvsub(velB, velA));
}

Vec2 PhysicsCollisionPair::computeContactCenter() const
{
    if (!_valid || _arbiter == nullptr)
    {
        return Vec2::ZERO;
    }

    int count = cpArbiterGetCount(_arbiter);
    if (count <= 0)
    {
        return Vec2::ZERO;
    }

    cpVect center = cpvzero;
    for (int i = 0; i < count; ++i)
    {
        cpVect a = cpArbiterGetPointA(_arbiter, i);
        cpVect b = cpArbiterGetPointB(_arbiter, i);
        center = cpvadd(center, cpvmult(cpvadd(a, b), 0.5f));
    }

    return PhysicsHelper::cpv2point(cpvmult(center, 1.0f / count));
}

NS_CC_END

#endif // CC_USE_PHYSICS

